    chatId,
    text: v.nota + '/100 · ' + v.job.title + '\n' + v.job.empresa + ' · publicada em ' + data + '\n\n' + v.motivo,
    reply_markup: { inline_keyboard: [
      [{ text: 'Quero', callback_data: 'q:' + v.id }, { text: 'Ignorar', callback_data: 'x:' + v.id }],
      [{ text: 'Abrir vaga', url: v.job.link }],
    ] },
  } });
}
return out;

